import{_ as t,a,c as l,ac as r}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"足球规则 · 七、三个完整判罚场景至官方来源与核对范围","description":"十一人制足球的比赛流程、越位、手球、犯规判罚与定位球规则","frontmatter":{"title":"足球规则 · 七、三个完整判罚场景至官方来源与核对范围","description":"十一人制足球的比赛流程、越位、手球、犯规判罚与定位球规则","splitFrom":"life/personal/sports/football-rules.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"足球规则","summary":"十一人制足球的比赛流程、越位、手球、犯规判罚与定位球规则","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"足球规则 · 适用范围与版本至六、守门员与换人的特殊规则","link":"/life/personal/sports/football-rules-part-01"},"next":{"text":"网球规则","link":"/life/personal/sports/tennis-rules"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"足球规则 · 适用范围与版本至六、守门员与换人的特殊规则","link":"/life/personal/sports/football-rules-part-01"},"next":{"text":"网球规则","link":"/life/personal/sports/tennis-rules"}},"headers":[],"relativePath":"life/personal/sports/football-rules-part-02.md","filePath":"life/personal/sports/football-rules-part-02.md"}'),o={name:"life/personal/sports/football-rules-part-02.md"};function i(n,e,s,d,p,f){return a(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="足球规则-·-七、三个完整判罚场景至官方来源与核对范围" tabindex="-1">足球规则 · 七、三个完整判罚场景至官方来源与核对范围 <a class="header-anchor" href="#足球规则-·-七、三个完整判罚场景至官方来源与核对范围" aria-label="Permalink to &quot;足球规则 · 七、三个完整判罚场景至官方来源与核对范围&quot;">​</a></h1><p><a href="/life/personal/sports/football-rules">返回分篇目录</a></p><p>足球的基本目标是在规定时间内，将球合法地整体送入对方球门。判断争议时，先看球是否还在比赛中，再看具体行为，最后确定如何恢复比赛以及是否出牌。</p><h2 id="七、三个完整判罚场景" tabindex="-1">七、三个完整判罚场景 <a class="header-anchor" href="#七、三个完整判罚场景" aria-label="Permalink to &quot;七、三个完整判罚场景 {#七、三个完整判罚场景}&quot;">​</a></h2><ol><li><strong>后卫在罚球区线上鲁莽绊倒攻方。</strong> 接触点在线上，属于罚球区内；判点球，鲁莽动作另给黄牌。判点球不是因为“攻方倒进了禁区”，而是看犯规发生的位置和类型。此例对应 IFAB Law 1 官方问答。</li><li><strong>前锋处于越位位置，却没有接球。</strong> 队友射门时，他站在门将前方遮住视线并影响扑救，仍可能因干扰对手判越位，进球无效；若他没有干扰任何人，也未参与比赛，则不能仅凭站得靠前取消进球。位置与行为要分两步判断。</li><li><strong>1∶1 的淘汰赛进入点球决胜。</strong> 前五轮双方各进四球，第六轮甲进、乙也进，仍然继续；到第七轮甲进、乙未进，才分出胜负。甲在第六轮先罚进时不能立即宣布获胜，双方须比较相同轮次。这里的小分不添加到正常比赛的进球数中。</li></ol><h2 id="八、从开球到攻守转换-新手看什么" tabindex="-1">八、从开球到攻守转换：新手看什么 <a class="header-anchor" href="#八、从开球到攻守转换-新手看什么" aria-label="Permalink to &quot;八、从开球到攻守转换：新手看什么 {#八、从开球到攻守转换-新手看什么}&quot;">​</a></h2><p>一支队通常分为守门员、后卫、中场、前锋。除守门员在本方罚球区内按规定用手外，这些称呼是分工，规则并不禁止后卫带球进攻或前锋回防。</p><p>一次进攻可以从后场传球开始：后卫提供接应，中场转移球的方向，边路队员拉开宽度，前锋寻找接球或射门空间。失去球权后，队员又要决定就近争抢还是退回保护空间。这些是理解比赛的观察线索，并非每支球队都必须采用的套路。</p><table tabindex="0"><thead><tr><th>术语</th><th>与规则联系起来理解</th></tr></thead><tbody><tr><td>控球、传切</td><td>持续处理球、传球后跑向新位置；跑位时仍要留意越位判定瞬间</td></tr><tr><td>直塞</td><td>传向防线身后的空间；球传到身后不自动构成越位</td></tr><tr><td>逼抢、反击</td><td>争夺处理球时间、夺回球后快速进攻；先抢到球不免除随后犯规责任</td></tr><tr><td>定位球</td><td>角球、任意球等恢复比赛机会的常用总称；各自的直接得分与越位规则不同</td></tr><tr><td>人墙</td><td>防守任意球时组成的队列，须满足距离等要求</td></tr><tr><td>有利</td><td>裁判认为继续比赛对被犯规方有利而暂不鸣哨，纪律处罚可稍后执行</td></tr><tr><td>VAR</td><td>获准赛事中的视频助理裁判体系；并非每场都有，也不是所有争议都检查</td></tr></tbody></table><p>上场前先确认比赛人数、换人方式、是否回场换人，以及平局如何处理。听到哨声后先停止动作，观察裁判手势和恢复比赛的位置；仅凭是否出牌不能推断下一次一定是直接任意球、点球还是界外球。</p><h2 id="九、观赛与上场自测" tabindex="-1">九、观赛与上场自测 <a class="header-anchor" href="#九、观赛与上场自测" aria-label="Permalink to &quot;九、观赛与上场自测 {#九、观赛与上场自测}&quot;">​</a></h2><ol><li>球仍有一小部分压着边线，是否出界？</li><li>前锋直接接到队友掷来的界外球，身前只有门将，是否越位？</li><li>越位位置的前锋接到门将扑出的射门并进球，是否有效？</li><li>后卫在罚球区内做危险抬脚动作但没有接触对手，是否必判点球？</li><li>门将手持球 7 秒后连续拍球 3 秒，是否重新计时？</li></ol><p><strong>答案：</strong> ①没有，必须整体越线。②直接接界外球不判越位。③若他在队友射门时已处越位位置，接扑救球获利通常越位。④不必然，单纯无接触的危险动作通常判间接任意球。⑤不重新计时，超过 8 秒应判对方角球。</p><h2 id="官方来源与核对范围" tabindex="-1">官方来源与核对范围 <a class="header-anchor" href="#官方来源与核对范围" aria-label="Permalink to &quot;官方来源与核对范围 {#官方来源与核对范围}&quot;">​</a></h2><ul><li><a href="https://www.theifab.com/laws/latest/" target="_blank" rel="noopener noreferrer">IFAB 规则总入口</a>：可切换赛季，阅读时应确认所选版本。</li><li><a href="https://www.theifab.com/laws/latest/the-field-of-play/" target="_blank" rel="noopener noreferrer">Law 1：比赛场地</a>：尺寸、罚球区与球门区，以及罚球区线上犯规的官方问答。</li><li><a href="https://www.theifab.com/laws/latest/the-players/" target="_blank" rel="noopener noreferrer">Law 3：队员</a>：人数、换人和 10 秒离场程序。</li><li><a href="https://www.theifab.com/laws/latest/the-duration-of-the-match/" target="_blank" rel="noopener noreferrer">Law 7：比赛时间</a>：半场长度与补时。</li><li><a href="https://www.theifab.com/laws/latest/offside/" target="_blank" rel="noopener noreferrer">Law 11：越位</a>：越位位置、参与比赛、主动处理球和例外。</li><li><a href="https://www.theifab.com/laws/latest/fouls-and-misconduct/" target="_blank" rel="noopener noreferrer">Law 12：犯规与不正当行为</a>：手球、纪律处分、守门员 8 秒控球及官方判例。</li></ul><p>以上重点章节已于 2026 年 10 月 23 日读取官方正文。链接中的 <code>latest</code> 会随赛季更新，本文版本说明固定为 2026/27；具体比赛的特殊规程仍需另查。</p>',16)])])}const u=t(o,[["render",i]]);export{c as __pageData,u as default};
